-- Replace only untouched demo imagery/content. Keep custom uploaded/linked images and edited names.
UPDATE product SET product_name='Áo kiểu cổ nhún cài cúc', material='Vải thô', gender='Female' WHERE product_id=1 AND product_name='Áo sơ mi linen dáng rộng' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=1 AND i.image_url='/assets/product-1.svg');
UPDATE product SET product_name='Quần dạ công sở dáng suông', material='Vải dạ', gender='Female' WHERE product_id=2 AND product_name='Quần ống rộng thường ngày' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=2 AND i.image_url='/assets/product-2.svg');
UPDATE product SET product_name='Đầm sơ mi kẻ sọc tay lỡ', material='Vải dệt', gender='Female' WHERE product_id=3 AND product_name='Đầm midi dáng mềm mại' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=3 AND i.image_url='/assets/product-3.svg');
UPDATE product SET product_name='Áo thun tăm dài tay cổ tròn', material='Vải thun', gender='Female' WHERE product_id=4 AND product_name='Áo thun cotton cơ bản' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=4 AND i.image_url='/assets/product-4.svg');
UPDATE product SET product_name='Quần jeans ống rộng', material='Denim', gender='Female' WHERE product_id=5 AND product_name='Quần jeans dáng đứng' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=5 AND i.image_url='/assets/product-5.svg');
UPDATE product SET product_name='Balo vải phong cách tối giản', material='Vải', gender='Unisex' WHERE product_id=6 AND product_name='Túi tote vải canvas' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=6 AND i.image_url='/assets/product-6.svg');
UPDATE product SET product_name='Áo nỉ cổ cao tay bồng', material='Vải nỉ', gender='Female' WHERE product_id=7 AND product_name='Áo cardigan dệt nổi' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=7 AND i.image_url='/assets/product-7.svg');
UPDATE product SET product_name='Quần short dạ dáng chữ A', material='Vải dạ', gender='Female' WHERE product_id=8 AND product_name='Quần short thanh lịch' AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=8 AND i.image_url='/assets/product-8.svg');
UPDATE product_variant SET color=CASE product_id WHEN 1 THEN 'Xanh pastel' WHEN 2 THEN 'Nâu ô liu' WHEN 3 THEN 'Kẻ xanh trắng' WHEN 4 THEN 'Trắng' WHEN 5 THEN 'Xanh denim' WHEN 6 THEN 'Xanh than' WHEN 7 THEN 'Kem' WHEN 8 THEN 'Nâu' END WHERE product_id BETWEEN 1 AND 8 AND color IN ('Màu cát','Xanh ô liu') AND EXISTS (SELECT 1 FROM product_image i WHERE i.product_id=product_variant.product_id AND i.image_url=CONCAT('/assets/product-',product_variant.product_id,'.svg'));
UPDATE product_image SET image_url=CONCAT('/assets/photos/product-',product_id,'.jpg') WHERE product_id BETWEEN 1 AND 8 AND image_url=CONCAT('/assets/product-',product_id,'.svg');
